  /* Verify the set */

  if (set == NULL)
    {
      return -EINVAL;
    }
  else
    {
      /* Set all elements */

      for (i = 0; i < _SIGSET_NELEM; i++)
        {
          set->_elem[i] = 0xffffffff;
        }
      return OK;
    }
}

/****************************************************************************
 * Name: sigfillset
 *
 * Description:
 *   This function initializes the signal set specified by set to full, with
 *   all signals included in the set.
 *
 * Input Parameters:
 *   set - Signal set to initialize
 *
 *  Returned Value:
 *   0 (OK), or -1 (ERROR) if the set argument is invalid.
 *
 * Assumptions:
 *
 ****************************************************************************/

int sigfillset(FAR sigset_t *set)
{
  int ret;

  /* Let nxsig_fillset do all the work. */

  ret = nxsig_fillset(set);
  if (ret < 0)
    {
      set_errno(EINVAL);
      ret = ERROR;
    }

  return ret;
